insert into words (deck_id, term, translation, "order", image_url)
select d.id, v.t, v.tr, v.o, case when v.k = '' then null else (
  select x.image_url from words x join word_decks xd on xd.id = x.deck_id and xd.deleted_at is null
  where x.image_url is not null and lower(trim(x.term)) = lower(trim(v.t))
    and (v.k = 's' or (select coalesce(array_agg(distinct left(w,4)),'{}') from regexp_split_to_table(replace(lower(coalesce(x.translation,'')),'ё','е'), '[^а-я]+') w
  where length(w)>=3 and w not in ('что','кто','кого','чем','чего','либо','нибудь','себя','свой','быть','очень','такой','этот','который')) && (select coalesce(array_agg(distinct left(w,4)),'{}') from regexp_split_to_table(replace(lower(coalesce(v.tr,'')),'ё','е'), '[^а-я]+') w
  where length(w)>=3 and w not in ('что','кто','кого','чем','чего','либо','нибудь','себя','свой','быть','очень','такой','этот','который')))
  order by x.id desc limit 1) end
from (values ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · понятия', 'quality', 'качество', 17, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · действия', 'range', 'зд. варьироваться', 7, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · фразы', 'result in', 'приводить к, давать в результате', 15, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · фразы', 'rising world temperatures', 'повышение температуры на Земле', 16, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · действия', 'rot', 'гнить, разлагаться', 8, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · понятия', 'scallop', 'гребешок', 18, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · фразы', 'scenery', 'пейзаж, вид', 17, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · фразы', 'seabed', 'морское дно', 18, 'r'), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · фразы', 'set down', 'записывать', 19, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · фразы', 'set up', 'устанавливать', 20, ''), ('Module 8: Challenges', false, 'Module 8 · другие слова', 'truly', 'действительно, в самом деле', 13, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · описание', 'unspoilt', 'неиспорченный', 3, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · действия', 'vanish', 'исчезать', 9, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · фразы', 'wilderness', 'дикая местность, пустыня', 21, ''), ('Module 8: Challenges', false, 'Going Green 8 – The Challenge of Antarctica · описание', 'worrying', 'тревожный, вызывающий беспокойство', 4, '')) v(f, sub, dk, t, tr, o, k)
join deck_folders m on m.title = v.f and m.parent_folder_id = (select id from deck_folders where title='Spotlight 9' and deleted_at is null) and m.deleted_at is null
left join deck_folders s on s.parent_folder_id = m.id and s.title = 'Другие слова' and s.deleted_at is null
join word_decks d on d.folder_id = case when v.sub then s.id else m.id end and d.title = v.dk and d.deleted_at is null
where not exists (select 1 from words y where y.deck_id = d.id and y.term = v.t and y."order" = v.o)
returning id;